\label{thm:diag}
Let $1\le s,p\le\infty$, $\mu>\max\{0,\bar a(s)\}$ and $0<\delta<1$.
\begin{itemize}
\item[\rm(i)] For every finite nonempty set $\Omega\subset\mathbb N_0$ and every
real sequence $\nu=(\nu_k)_{k\in\Omega}$
\begin{equation}\label{eq:diaglow}
e_\delta(W_s^\mu,\psi_\nu G_\Omega,C(\mathbb R),\ell_p)\ge c\,\delta^{e_{\mathrm{tr}}} ,
\end{equation}
where $c=c(s,p,\mu)>0$ depends neither on $\Omega$, nor on $\nu$, nor on $\operatorname{card}(\Omega)$.
\item[\rm(ii)] If $s\ge4/3$ or $p\le4/3$, then
$\mathcal E_\delta(W_s^\mu,\Psi,C(\mathbb R),\ell_p)\ge c\,\delta^{e_{\mathrm{tr}}}$.
If, moreover, $s\ne4/3$ and $p\ne4/3$, then
\begin{equation}\label{eq:regular-minimax}
c\,\delta^{e_{\mathrm{tr}}}
\le\mathcal E_\delta(W_s^\mu,\Psi,C(\mathbb R),\ell_p)
\le C\,\delta^{e_{\mathrm{tr}}},
\end{equation}
and for $s=4/3$ or $p=4/3$ the upper bound has the form
$\mathcal E_\delta(W_s^\mu,\Psi,C(\mathbb R),\ell_p)\le C\,\delta^{e_{\mathrm{tr}}}
\bigl(\log(\mathrm e/\delta)\bigr)^{1/4}$. Here $c,C>0$ depend only on $s,p,\mu$.
\item[\rm(iii)] Every fixed method of the class $\mathcal S^\theta$ with $\theta>\beta$ at the level
$N_*=\lceil\delta^{-1/\rho}\rceil$ has error \eqref{eq:localerror} not exceeding
$C\delta^{e_{\mathrm{tr}}}$ for $s\ne4/3$, $p\ne4/3$ and not exceeding
$C\delta^{e_{\mathrm{tr}}}(\log(\mathrm e/\delta))^{1/4}$ for $s=4/3$ or $p=4/3$, where $C$
depends also on $\theta$ and $C(\nu)$.
\end{itemize}

\label{sum:point}
There exist absolute constants $C\ge c>0$ with the following properties.
\begin{itemize}
\item[\rm(i)] For all $x\in\mathbb R$ and all $k\ge0$
\begin{equation}\label{sum:env}
|h_k(x)|\le C\bigl(\lambda_k^{1/3}+|x^2-\lambda_k|\bigr)^{-1/4},
\end{equation}
and in particular
\begin{equation}\label{sum:envmax}
|h_k(x)|\le C\,(k+1)^{-1/12} .
\end{equation}
\item[\rm(ii)] For all $k\ge0$
\begin{equation}\label{sum:maxlow}
\max_{x\in\mathbb R}|h_k(x)|\ge c\,(k+1)^{-1/12} .
\end{equation}
\end{itemize}

\label{sum:kernel}
Let $1\le q<\infty$ and
$$
K_{N,q}:=\sup_{x\in\mathbb R}\sum_{k=0}^{N}|h_k(x)|^q .
$$
Then
\begin{equation}\label{sum:law}
K_{N,q}\asymp\sum_{j=1}^{N+1}j^{-q/4}
\end{equation}
with constants depending on $q$ and not depending on $N$. Moreover,
\begin{equation}\label{sum:law_cases}
K_{N,q}\asymp
\left\{
\begin{array}{ll}
1,& q>4,\\[1mm]
\log(2+N),& q=4,\\[1mm]
(N+1)^{1-q/4},& 1\le q<4 .
\end{array}
\right.
\end{equation}

Fix $x$. The numbers $\lambda_k$ are spaced $2$ apart, so on each
side of $x^2$ the $j$-th closest of them ($j=0,1,\ldots$) is separated from $x^2$ by at least $2j$. Hence, if
the numbers $|x^2-\lambda_k|$, $0\le k\le N$, are arranged in increasing order, then the $i$-th of them
($i=0,1,\ldots,N$) is at least $\lfloor i/2\rfloor$. Since $\lambda_k^{1/3}\ge1$, estimate
\eqref{sum:env} gives
$$
\sum_{k=0}^N|h_k(x)|^q\le C^q\sum_{i=0}^N\bigl(1+\lfloor i/2\rfloor\bigr)^{-q/4}
\le2C^q\sum_{j=1}^{N+1}j^{-q/4}
$$
uniformly in $x$. For the lower bound take $x=0$. For $q>4$ or $N\le1$ it suffices that
$K_{N,q}\ge|h_0(0)|^q=\pi^{-q/4}$. For $1\le q\le4$ and $N\ge2$, by \eqref{zero}--\eqref{wallis}
\begin{equation}\label{sum:low}
\sum_{k=0}^N|h_k(0)|^q
\ge \sum_{1\le r\le N/2}|h_{2r}(0)|^q
\gtrsim_q \sum_{1\le r\le N/2}r^{-q/4}
\asymp_q \sum_{j=1}^{N+1}j^{-q/4} .
\end{equation}
The equivalence of \eqref{sum:law} and \eqref{sum:law_cases} is a comparison of the sum with an integral.
$\Box$

\label{lem:blockest}
Let $1\le s\le\infty$ and $q=s/(s-1)$. Then for all $M\in\mathbb N$ and $x\in\mathbb R$
\begin{equation}\label{eq:blockkernel}
\Bigl(\sum_{M\le k<2M}|h_k(x)|^q\Bigr)^{1/q}\le C\,M^{\bar a(s)}L_s(M),
\end{equation}
where for $s=1$ the left-hand side is $\max_{M\le k<2M}|h_k(x)|$, and $C$ depends only on $s$.

\label{lem:noise}
Let $1\le p\le\infty$, $p'=p/(p-1)$, $f\in {\cal L}_2(\mathbb R)$, and let
\eqref{perturbation} hold. Then for every method of $\mathcal S^\theta$ and for every $N\ge1$
\begin{equation}\label{eq:sigma}
\|S_N^\nu f-S_N^\nu\mathbf f^\delta\|_\infty
\le\bigl(1+C(\nu)\bigr)\delta\,K_{N,p'}^{1/p'}
\le c\,\delta N^{a_+(p)}L_p(N) ,
\end{equation}
where for $p=1$ the quantity $K_{N,\infty}^{1/\infty}$ is replaced by $\max_{k\le N}\|h_k\|_\infty$, and $c$
depends only on $p$ and $C(\nu)$.

\label{lem:block}
There exist absolute constants $\kappa_0=19/50$, $\kappa\in(0,1)$, $c_1>0$ and an integer $N_0$ such that
for every integer $N\ge N_0$ and every set $\Omega$ of $N$ distinct integers of the
interval $[N,3N]$ the following holds.
\begin{itemize}
\item[\rm(i)] At the point $x_0=\kappa_0 N^{-1/2}$, for all integers $k\in[N,3N]$,
\begin{equation}\label{bulkpoint}
|h_k(x_0)|\ge\frac1{4\sqrt\pi}\,k^{-1/4} ,
\end{equation}
and therefore, for $\varepsilon_k=\operatorname{sign}h_k(x_0)$,
\begin{equation}\label{bulksum}
\Bigl\|\sum_{k\in\Omega}\varepsilon_k h_k \Bigr\|_\infty
\ge\sum_{k\in\Omega}|h_k(x_0)|
\ge\frac{3^{-1/4}}{4\sqrt\pi}\,N^{3/4} .
\end{equation}
\item[\rm(ii)] There exist a set $W\subset\Omega$ with $\operatorname{card}(W)\ge\kappa N^{1/3}$ and a point
$x_W$ such that $|h_k(x_W)|\ge c_1N^{-1/12}$ for all $k\in W$.
\item[\rm(iii)] For any $1\le s\le\infty$ and $\mu>0$ the function
$$
f=(3N)^{-\mu}N^{-1/s}\sum_{k\in\Omega}\varepsilon_k h_k
$$
with the signs from {\rm(i)} satisfies $\|f\|_{s,\mu}\le1$, its coefficients $a_k(f)$ vanish
outside $\Omega$, and
\begin{equation}\label{blocktail}
\|f\|_\infty\ge\tfrac1{10}\,3^{-\mu}N^{-\mu+3/4-1/s} .
\end{equation}
\end{itemize}
